/// <reference types="node" />
/**
 * Automated Feature-Sliced Design checks (docs/ARCHITECTURE.md → Frontend):
 *  1. Layers only import downwards: app → pages → widgets → features → entities → shared.
 *  2. Another slice is reached only through its public API: '@/features/select-look', never an inner file.
 *  3. Slices on the same layer never import each other (shared and app are exempt).
 * Folders generated by Wayfinder (actions, routes, wayfinder) count as the shared layer.
 */
import { readFileSync, readdirSync, statSync } from 'node:fs';
import { dirname, join, relative, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { describe, expect, it } from 'vite-plus/test';

const ROOT = fileURLToPath(new URL('..', import.meta.url));
const RANK: Record<string, number> = {
    shared: 0,
    actions: 0,
    routes: 0,
    wayfinder: 0,
    entities: 1,
    features: 2,
    widgets: 3,
    pages: 4,
    app: 5,
};
const SLICED = new Set(['entities', 'features', 'widgets', 'pages']);
const GENERATED = new Set(['actions', 'routes', 'wayfinder']);

function walk(dir: string): string[] {
    return readdirSync(dir).flatMap((name) => {
        const path = join(dir, name);
        if (statSync(path).isDirectory())
            return GENERATED.has(name) && dir === ROOT ? [] : walk(path);
        return /\.(ts|vue)$/.test(name) && !name.endsWith('.d.ts')
            ? [path]
            : [];
    });
}

type Location = { layer: string; slice: string | null };

function locate(pathFromRoot: string): Location {
    const [layer, slice] = pathFromRoot.split('/');
    return { layer, slice: SLICED.has(layer) ? slice : null };
}

function importsOf(file: string): string[] {
    const code = readFileSync(file, 'utf8');
    return [
        ...code.matchAll(/(?:import|export)\s[^;]*?from\s+['"]([^'"]+)['"]/g),
    ].map((m) => m[1]);
}

const violations: string[] = [];

for (const file of walk(ROOT)) {
    const fromRel = relative(ROOT, file);
    const from = locate(fromRel);

    for (const spec of importsOf(file)) {
        let target: string;
        if (spec.startsWith('@/')) target = spec.slice(2);
        else if (spec.startsWith('.'))
            target = relative(ROOT, resolve(dirname(file), spec));
        else continue;

        const to = locate(target);
        if (!(to.layer in RANK)) continue;

        if (RANK[to.layer] > RANK[from.layer]) {
            violations.push(`${fromRel}: imports a higher layer → ${spec}`);
        } else if (
            to.layer === from.layer &&
            SLICED.has(to.layer) &&
            to.slice !== from.slice
        ) {
            violations.push(`${fromRel}: imports a sibling slice → ${spec}`);
        } else if (
            SLICED.has(to.layer) &&
            to.slice !== from.slice &&
            target !== `${to.layer}/${to.slice}`
        ) {
            violations.push(`${fromRel}: bypasses the public API → ${spec}`);
        }
    }
}

describe('FSD architecture', () => {
    it('respects layer order, slice isolation and public APIs', () => {
        expect(violations).toEqual([]);
    });
});
